-- Stamp the provenance on every imported row so no record can be read as a signed
-- work order, and mark the area unknown rather than leaving it blank as if it were
-- simply not filled in.
UPDATE ghp_maintenance
   SET notes = 'นำเข้าจากไลน์กลุ่ม "ซ่อมได้" (10 ธ.ค. 68 – 31 ก.ค. 69) — บันทึกการแจ้งซ่อมตามข้อความจริง ไม่ใช่ใบแจ้งซ่อมที่ลงนาม'
               || CASE WHEN notes IS NULL OR notes='' THEN '' ELSE ' · ' || notes END,
       area = 'โรงงาน (ไม่ระบุในข้อความ)',
       modified = datetime('now')
 WHERE id LIKE 'MNT00%';
